import {readFile,writeFile} from 'node:fs/promises';
const literal=async file=>(await readFile(file,'utf8')).trim().replaceAll("'","''");
const template=await readFile('tools/cozy-life-template.sql','utf8');
await writeFile('supabase/server/19b-cozy-life.sql',
 '-- Generated by tools/build-cozy-life.mjs from its SQL template and shared home definitions.\n'+
 template.replace('__HOMES__',await literal('src/data/homes.json')).replace('__FURNISHINGS__',await literal('src/data/homeFurnishings.json')).replace('__PLANS__',await literal('src/data/neighborhoodPlans.json')));
